from fastapi import FastAPI
import pytest
from fastapi.testclient import TestClient

app = FastAPI()

@app.vibe("/vibe")
def vibe_endpoint():
    return {"message": "vibe check passed"}

client = TestClient(app)

def test_vibe():
    # Using a custom method VIBE via TestClient (which uses requests)
    # requests.request allows specifying any method
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibe check passed"}

if __name__ == "__main__":
    try:
        test_vibe()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)
EOF
